avior are not configurable. volumeType -&gt; (string) The Amazon EBS volume type. If you do not specify a type, the default is gp3 . Possible values: o standard o io1 o io2 o gp2 o sc1 o st1 o gp3 iops -&gt; (integer) The number of IOPS to provision. For gp3 , io1 , and io2 volumes, this is the number of IOPS provisioned for the volume. For gp2 volumes, this sets the baseline IOPS per- formance. It also controls the rate at which the volume accumulates I/O credits for bursting. Supported values: gp3 , 3,00080,000; io1 , 10064,000; io2 , 100256,000. Constraints: o min: 100 o max: 256000 throughput -&gt; (integer) The throughput to provision, in MiB/s. Valid only for gp3 volumes. Valid range: 1252,000 MiB/s. Constraints: o min: 125 o max: 2000 encrypted -&gt; (boolean) Specifies whether to encrypt the volume. Encrypted vol- umes can be attached only to instances that support Ama- zon EBS encryption. If you create a volume from a snap- shot, you cannot specify an encryption value. kmsKeyId -&gt; (string) The identifier (key ID, key alias, key ARN, or alias ARN) of the customer managed KMS key to use for Amazon EBS en- cryption. Constraints: o min: 20 o max: 2048 o pattern: arn:aws(-[^:]+)?:kms:[a-z0-9-]+:[0-9]{12}:key/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12} freeSpaceGiB -&gt; (integer) The free space guaranteed on the root volume, in GiB. AgentCore adds the operating system overhead on top of this value. The default is 8 GiB. Constraints: o min: 2 o max: 65000 JSON Syntax: { "ec2Configuration": { "launchTemplateSource": { "launchParameters": { "operatingSystem": "LINUX_X86_64"|"LINUX_ARM64", "instanceRequirements": { "allowedInstanceTypes": ["string", ...] }, "ephemeralVolumes": [ { "deviceName": "string", "virtualName": "string", "ebs": { "volumeType": "standard"|"io1"|"io2"|"gp2"|"sc1"|"st1"|"gp3", "iops": integer, "throughput": integer, "encrypted": true|false, "kmsKeyId": "string", "snapshotId": "string", "volumeSize": integer, "volumeInitializationRate": integer, "ebsCardIndex": integer } } ... ], "monitoring": "BASIC"|"DETAILED", "licenseSpecifications": [ { "licenseConfigurationArn": "string" } ... ], "capacityReservationSpecification": { "capacityReservationPreference": "capacity-reservations-only"|"open"|"none", "capacityReservationTarget": { "capacityReservationId": "string", "capacityReservationResourceGroupArn": "string" } }, "sshKeyName": "string", "instanceProfileArn": "string", "propagatedTags": {"string": "string" ...} } }, "vpcConfiguration": { "subnets": ["string", ...], "securityGroups": ["string", ...] }, "volumes": [ { "ebsConfiguration": { "name": "string", "sizeGiB": integer, "volumeType": "standard"|"io1"|"io2"|"gp2"|"sc1"|"st1"|"gp3", "iops": integer, "throughput": integer, "encrypted": true|false, "kmsKeyId": "string", "snapshotId": "string" } } ... ], "lifecycleConfiguration": { "idleInstanceTimeout": integer, "maxLifetime": integer }, "rootVolume": { "volumeType": "standard"|"io1"|"io2"|"gp2"|"sc1"|"st1"|"gp3", "iops": integer, "throughput": integer, "encrypted": true|false, "kmsKeyId": "string", "freeSpaceGiB": integer } } }
    /// </summary>
    [CliOption("--compute-configuration")]
    public string? ComputeConfiguration { get; private init; }

